import { AddressCopyLink } from '@cetus/design'
import SingleTokenInfo from '@cetus/design/src/components/common/SingleTokenInfo'
import useExplorer from '@cetus/hooks/src/useExplorer'
import { useGetToken } from '@cetus/hooks/src/useToken'
import { SingleCoinImage } from '@cetus/ui-kit'
import { cancelBubble } from '@cetus/utils'
import { Center, HStack, Popover, PopoverBody, PopoverContent, PopoverTrigger, Portal, Skeleton, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

const CoinSingerInfo = ({ coinType }: { coinType: any }) => {
  const [isShowInfo, setIsShowInfo] = useState(false)
  const { getTokenInfo } = useGetToken()
  const [tokenInfo, setTokenInfo] = useState<any>(null)

  useEffect(() => {
    const fetchToken = async () => {
      if (!coinType) return
      try {
        const coinInfo = await getTokenInfo(coinType)
        console.log('🚀 ~ fetchToken ~ coinInfo:', coinInfo)
        setTokenInfo(coinInfo)
      } catch (error) {
        console.error('Error fetching token info:', error)
      }
    }
    fetchToken()
  }, [coinType])

  return (
    <HStack p="12px 0" onClick={e => cancelBubble(e)} onMouseEnter={() => setIsShowInfo(true)} onMouseLeave={() => setIsShowInfo(false)}>
      <Popover isOpen={isShowInfo} placement="top-start">
        <PopoverTrigger>
          <Center>
            <Skeleton isLoaded={!!tokenInfo}>
              <SingleTokenInfo token={tokenInfo} />
            </Skeleton>
          </Center>
        </PopoverTrigger>
        {isShowInfo && (
          <Portal>
            <PopoverContent zIndex="2" minW="unset" w="unset" border="1px solid" borderColor="border" p="4px ">
              <PopoverBody borderRadius="12px">
                <TooltipInfo tokenInfo={tokenInfo} />
              </PopoverBody>
            </PopoverContent>
          </Portal>
        )}
      </Popover>
    </HStack>
  )
}

const TooltipInfo = ({ tokenInfo }: { tokenInfo: any }) => {
  const { getExplorerUrl } = useExplorer()
  return (
    <VStack align="flex-start">
      <HStack w="100%">
        <SingleCoinImage imageUrl={tokenInfo?.logo_url} w="20px" h="20px" showTag={!tokenInfo?.is_trusted} showTagWidth="10px" showTagHeight="10px" />
        <Text fontSize="12px">{tokenInfo?.symbol}</Text>
        <AddressCopyLink
          address={tokenInfo?.coin_type}
          color="text_caption"
          onClickLink={() => {
            window.open(getExplorerUrl(tokenInfo?.coin_type, 'coin'), '_blank')
          }}
        />
      </HStack>
    </VStack>
  )
}
export default CoinSingerInfo
