import { Area, AreaChart, ResponsiveContainer, Tooltip, XAxis } from 'recharts'

import CustomizedAxisTick from './CustomizedAxisTick'
import EmptyTooltip from './EmptyTooltip'

const TvlChart = ({ data, onChangeValue }: { data: any; onChangeValue: (data: any) => void }) => {
  const handleMouseMove = (e: any) => {
    if (e && e.activePayload && e.activePayload.length) {
      console.log('🚀 ~ handleMouseMove ~ e.activePayload[0]:', e.activePayload[0])
      onChangeValue(e.activePayload[0].payload)
    }
  }

  const handleMouseLeave = () => {
    onChangeValue(null)
  }

  return (
    <ResponsiveContainer width="100%" height="100%">
      <AreaChart data={data} onMouseMove={handleMouseMove} onMouseLeave={handleMouseLeave}>
        <defs>
          <linearGradient id="colorTvlArea" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#0080FF" stopOpacity={0.2} />
            <stop offset="100%" stopColor="#17181D" stopOpacity={0.2} />
          </linearGradient>
        </defs>
        {/* <CartesianGrid strokeDasharray="3 3" /> */}
        <XAxis type="category" dataKey="month" minTickGap={18} tickLine={false} axisLine={false} tick={<CustomizedAxisTick />} />
        {/* <YAxis /> */}
        <Tooltip content={<EmptyTooltip />} cursor={{ stroke: 'rgba(255, 255, 255, 0.6)', strokeWidth: 1, strokeDasharray: '3 3' }} />
        <Area type="monotone" dataKey="num" stroke="#76C8FF" fill="url(#colorTvlArea)" isAnimationActive={false} />
      </AreaChart>
    </ResponsiveContainer>
  )
}

export default TvlChart
